import {
    Group,
    Mesh,
    MeshStandardMaterial,
    MeshBasicMaterial,
    CylinderGeometry,
    PlaneGeometry,
    CircleGeometry,
    Color,
    Vector3,
    Object3D
} from 'three/webgpu';
import {
    NodeMaterial,
    mix,
    uv,
    color
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import textUtils from '@/text';

export default function createNode(config, ctx) {
    const root = new Group();
    root.position.set(
        (config.position?.[0] ?? 0),
        (config.position?.[1] ?? 0),
        (config.position?.[2] ?? 0)
    );
    root.rotation.set(
        (config.rotation?.[0] ?? 0),
        (config.rotation?.[1] ?? 0),
        (config.rotation?.[2] ?? 0)
    );
    root.scale.set(
        (config.scale?.[0] ?? 1),
        (config.scale?.[1] ?? 1),
        (config.scale?.[2] ?? 1)
    );

    // ---------- WATCH MESH ----------
    const watchGroup = ctx.glbLoader(config.meshUrl);
    root.add(watchGroup);

    // ---------- PLINTH ----------
    const plinthGeom = new CylinderGeometry(1.4, 1.4, 0.25, 32);
    const plinthMat = new MeshStandardMaterial({
        color: new Color('#14141a'),
        metalness: 0.3,
        roughness: 0.7
    });
    const plinthMesh = new Mesh(plinthGeom, plinthMat);
    // Top face at y = -1.1 => center y = -1.1 - 0.125
    plinthMesh.position.y = -1.225;
    root.add(plinthMesh);

    // ---------- BACKDROP GRADIENT ----------
    const backdropGeom = new PlaneGeometry(7, 6);
    const gradientNode = mix(
        color('#0b0b10'),
        color('#16161d'),
        uv().y
    );
    const backdropMat = new NodeMaterial();
    backdropMat.colorNode = gradientNode;
    const backdropMesh = new Mesh(backdropGeom, backdropMat);
    backdropMesh.position.set(0, 0, -2.5);
    root.add(backdropMesh);

    // ---------- CONTACT SHADOW ----------
    const shadowGeom = new CircleGeometry(1.6, 64);
    const shadowMat = new MeshBasicMaterial({
        color: 0x000000,
        transparent: true,
        opacity: 0.55,
        depthWrite: false
    });
    const shadowMesh = new Mesh(shadowGeom, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = -1.35;
    root.add(shadowMesh);

    // ---------- TEXT ----------
    const createdTexts = [];

    const atlasId = config.atlas?.id ?? 0;
    const region = config.atlas?.region ?? { x: 0, y: 0, w: 512, h: 320 };

    // Headline
    if (config.textContent?.headline) {
        const headlineMesh = textUtils.createTextMesh({
            text: config.textContent.headline,
            fontFamily: 'Lora',
            fontWeight: 600,
            fontSize: 68,
            letterSpacing: -0.005,
            lineHeight: 1.1,
            color: config.colors?.ink ?? '#16161d',
            atlasId,
            region
        });
        headlineMesh.position.set(0, -1.5, 0);
        root.add(headlineMesh);
        createdTexts.push(headlineMesh);
    }

    // Body
    if (config.textContent?.body) {
        const bodyMesh = textUtils.createTextMesh({
            text: config.textContent.body,
            fontFamily: 'JetBrains Mono',
            fontWeight: 400,
            fontSize: 26,
            letterSpacing: 0,
            lineHeight: 1.5,
            color: config.colors?.ink ?? '#16161d',
            atlasId,
            region
        });
        bodyMesh.position.set(0, -1.9, 0);
        root.add(bodyMesh);
        createdTexts.push(bodyMesh);
    }

    // Caption
    if (config.textContent?.caption) {
        const captionMesh = textUtils.createTextMesh({
            text: config.textContent.caption,
            fontFamily: 'JetBrains Mono',
            fontWeight: 400,
            fontSize: 18,
            letterSpacing: 0.08,
            lineHeight: 1.4,
            color: config.colors?.accent ?? '#ff2a38',
            atlasId,
            region
        });
        captionMesh.position.set(0, -2.4, 0);
        root.add(captionMesh);
        createdTexts.push(captionMesh);
    }

    // ---------- CINEMATIC PRIMITIVES ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // ---------- USERDATA ----------
    const timelines = [];

    root.userData.handlers = {};

    root.userData.cleanup = () => {
        // Kill GSAP timelines
        timelines.forEach(t => t.kill());
        // Dispose geometries & materials we created
        plinthGeom.dispose();
        plinthMat.dispose();
        backdropGeom.dispose();
        backdropMat.dispose();
        shadowGeom.dispose();
        shadowMat.dispose();

        createdTexts.forEach(mesh => {
            if (mesh.geometry) mesh.geometry.dispose();
            if (mesh.material) {
                if (Array.isArray(mesh.material)) {
                    mesh.material.forEach(m => m.dispose());
                } else {
                    mesh.material.dispose();
                }
            }
        });
    };

    return root;
}
